# ---------- write PNG ----------
def png(path):
    raw = bytearray()
    for row in range(H):
        raw.append(0)
        raw += fb[row*W*3:(row+1)*W*3]
    def chunk(t, d):
        c = t + d
        return struct.pack('>I', len(d)) + c + struct.pack('>I', zlib.crc32(c) & 0xffffffff)
    ihdr = struct.pack('>IIBBBBB', W, H, 8, 2, 0, 0, 0)
    data = (chunk(b'IHDR', ihdr) + chunk(b'IDAT', zlib.compress(bytes(raw), 9))
            + chunk(b'IEND', b''))
    with open(path, 'wb') as f:
        f.write(b'\x89PNG\r\n\x1a\n' + data)

out_dir = os.environ.get('MAKEFUN_OUTPUT_DIR', 'out')
os.makedirs(out_dir, exist_ok=True)
png(os.path.join(out_dir, 'entry.png'))
print("wrote entry.png:", os.path.getsize(os.path.join(out_dir, 'entry.png')), "bytes")